// Robust JSON extractor — handles AI responses wrapped in markdown
// code fences, prose preambles, or trailing junk. Returns the parsed
// object or null. FROM v2 tryParseGeminiJSON (kernel helper).

engine.parseAiJson:
function parseAiJson(raw) {
  if (!raw) return null;
  var s = String(raw).trim();
  // Strip leading ```json or ``` fences.
  s = s.replace(/^```(?:json)?\s*/i, "").replace(/```$/, "").trim();
  try { return JSON.parse(s); } catch (e) { /* fall through */ }
  // Try to locate the outermost balanced JSON object/array.
  var startObj = s.indexOf("{");
  var startArr = s.indexOf("[");
  var start = -1;
  if (startObj === -1) start = startArr;
  else if (startArr === -1) start = startObj;
  else start = Math.min(startObj, startArr);
  if (start === -1) return null;
  var open = s[start];
  var close = open === "{" ? "}" : "]";
  var depth = 0;
  var inStr = false;
  var esc = false;
  for (var i = start; i < s.length; i++) {
    var c = s[i];
    if (esc) { esc = false; continue; }
    if (c === "\\") { esc = true; continue; }
    if (c === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (c === open) depth++;
    else if (c === close) {
      depth--;
      if (depth === 0) {
        try { return JSON.parse(s.substring(start, i + 1)); }
        catch (e) { return null; }
      }
    }
  }
  return null;
}

// Normalize the AI response shape. Coerces arrays/objects into a
// canonical { items: [...] } shape, classifies each item's category
// into "Risk" or "Usage", and clears `rule_applied` references that
// don't match an actual loaded rule.

engine.normalizeResponse:
function normalizeResponse(data, rules) {
  var out = data;
  if (Array.isArray(out)) {
    out = { items: out };
  } else if (out && typeof out === "object" && !out.items) {
    var foundKey = Object.keys(out).filter(function (k) {
      return Array.isArray(out[k]);
    })[0];
    out.items = foundKey ? out[foundKey] : [];
  } else if (!out || typeof out !== "object") {
    out = { items: [] };
  }
  if (Array.isArray(out.items) && out.items.length) {
    out.items.forEach(function (item) {
      if (!item.category) item.category = "Risk";
      var cat = String(item.category).toLowerCase().trim();
      if (cat.indexOf("risk") !== -1 || cat.indexOf("liability") !== -1 || cat.indexOf("issue") !== -1) {
        item.category = "Risk";
      } else if (
        cat.indexOf("usage") !== -1 ||
        cat.indexOf("ops") !== -1 ||
        cat.indexOf("operational") !== -1 ||
        cat.indexOf("restriction") !== -1
      ) {
        item.category = "Usage";
      } else {
        item.category = "Risk";
      }
    });
    var ruleNames = (Array.isArray(rules) ? rules : []).map(function (r) {
      return String(r.type || "").toLowerCase().trim();
    });
    out.items.forEach(function (item) {
      if (!item.rule_applied) return;
      var applied = String(item.rule_applied).toLowerCase().trim();
      var valid = ruleNames.some(function (name) {
        return name && (applied.indexOf(name) !== -1 || name.indexOf(applied) !== -1);
      });
      if (!valid) item.rule_applied = "";
    });
  } else if (out) {
    out.items = out.items || [];
  }
  return out;
}

