        var cat = String(item.category).toLowerCase().trim();
        if (cat.indexOf("risk") !== -1 || cat.indexOf("liability") !== -1 || cat.indexOf("issue") !== -1) {
          item.category = "Risk";
        } else if (
          cat.indexOf("usage") !== -1 ||
