  var footerHtml =
    '<button type="button" class="_eli3_lr_results_home">← HOME</button>';

  root.innerHTML = header + rulesBanner + overview + sectionHtml + footerHtml;
  mount.appendChild(root);

  // ─── Wire interactions ───────────────────────────────────────────
  // Overview collapse toggle.
  var overviewHead = root.querySelector('[data-toggle="overview"]');
  overviewHead.onclick = function () {
    var body = root.querySelector("#_eli3_lr_overview_body");
    var arrow = root.querySelector("#_eli3_lr_overview_arrow");
    var hint = root.querySelector("#_eli3_lr_overview_hint");
    if (!body) return;
    var isHidden = body.hasAttribute("hidden");
    if (isHidden) {
      body.removeAttribute("hidden");
      arrow.textContent = "▼";
      hint.style.opacity = "0";
    } else {
      body.setAttribute("hidden", "");
      arrow.textContent = "◀";
      hint.style.opacity = "1";
    }
  };

  // Section collapse toggle.
  var sectionHead = root.querySelector('[data-toggle="section"]');
  sectionHead.onclick = function () {
    var body = root.querySelector("#" + sectionId);
    var arrow = root.querySelector("#_eli3_lr_results_section_arrow");
    if (!body) return;
    var isHidden = body.hasAttribute("hidden");
    if (isHidden) {
      body.removeAttribute("hidden");
      arrow.textContent = "▼";
    } else {
      body.setAttribute("hidden", "");
      arrow.textContent = "◀";
    }
  };

  // Per-card action buttons — delegate so the row's interactive
  // elements don't compete with the section-collapse handler. The
  // "fix" data-action splits into onFix vs onDelete based on the
  // button's _delete CSS class (set when AI's fix_suggestion is a
  // deletion verb) — keeps the v2 separation while sharing the
  // attribute.
  Array.prototype.forEach.call(root.querySelectorAll("[data-action]"), function (btn) {
    btn.onclick = function (ev) {
      ev.stopPropagation();
      var idx = Number(btn.getAttribute("data-idx"));
      var item = combined[idx];
      if (!item) return;
      var action = btn.getAttribute("data-action");
      if (action === "locate") onLocate(item, btn);
      else if (action === "fix") {
        if (btn.classList.contains("_eli3_lr_results_btn_delete")) onDelete(item, btn);
        else onFix(item, btn);
      }
      else if (action === "dismiss") {
        onDismiss(item, btn);
        var card = root.querySelector("#_eli3_lr_card_" + idx);
        if (card && card.parentNode) card.parentNode.removeChild(card);
      }
    };
  });

  // Header close + footer Home — both go home. Speed-reader easter
  // egg (v2 line 50): if user closes within 3 seconds of render,
  // fire the trophy hook. Useful telemetry — "scanned + decided fast"
  // is a recognizable pattern that maps to a real achievement.
  function _onClose() {
    if (Date.now() - renderTs < 3000) {
      try { onCloseFast(); } catch (e) {}
    }
    onHome();
  }
  root.querySelector("._eli3_lr_results_close").onclick = _onClose;
  root.querySelector("._eli3_lr_results_home").onclick = _onClose;

  return {
    refresh: function () {
      // Caller re-runs renderResults for a fresh paint. Cheaper than
      // diffing — the page is shallow.
    },
  };
}

// renderRewriteEditor — v2-style FIX dialog port. Wraps the surgical
// redline editor that legal_risks (and historically Ask ELI) uses to
// preview AI rewrites and apply per-hunk track changes.
//
// FROM v2 showRewriteEditor (taskpane_v2.js:23048). v3 split:
//   • All Word.run / AI calls happen in init.js callbacks.
//   • View is pure DOM — only knows what's in opts.
//   • Word-diff + redline HTML come from kernel/engine helpers also
//     passed via opts (`computeDiff`, `renderHunkHtml`).
//
// opts:
//   originalText      string   initial value of the original textarea
//   instruction       string   initial AI instructions textarea value
//   isMissing         bool     true = writing from scratch, no original
//   onRunAI(instr, original) → Promise<aiText>
//   computeDiff(orig, ai)   → hunks
//   renderHunkHtml(hunks)   → string of HTML
//   onSyncSelection()       → Promise<{cleanText, status}>
//   onApplyAll(orig, ai, hunks)        → Promise<{ok, message}>
//   onApplyHunk(hunk, hunks, orig)     → Promise<{ok, found}>
//   onLocateAndApply(oldText, newText, scopeText, displayOldText)
//                                         → opens hunk-jumper UI
//   onFullReplace(aiText)              → void
//   onClose()                          → void

view.renderRewriteEditor:
function renderRewriteEditor(opts) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  opts = opts || {};
  var originalText = String(opts.originalText || "");
  var initialInstruction = String(opts.instruction ||
    "Rewrite this clause to be more favorable to Colgate-Palmolive, prioritizing our rights and limiting our liability.");
  var isMissing = !!opts.isMissing;
  var computeDiff = opts.computeDiff || function () { return []; };
  var renderHunkHtml = opts.renderHunkHtml || function () { return ""; };
  var onRunAI = opts.onRunAI || function () { return Promise.reject(new Error("onRunAI missing")); };
  var onSyncSelection = opts.onSyncSelection || function () { return Promise.resolve({ cleanText: originalText, status: "" }); };
  var onApplyAll = opts.onApplyAll || function () { return Promise.reject(new Error("onApplyAll missing")); };
  var onApplyHunk = opts.onApplyHunk || function () { return Promise.resolve({ ok: false, found: false }); };
  var onLocateAndApply = opts.onLocateAndApply || function () {};
  var onFullReplace = opts.onFullReplace || function () {};
  var onClose = opts.onClose || function () {};

  // Tear down any prior editor — re-FIX while one is open should swap.
  var prior = document.getElementById("_eli3_lr_rw_overlay");
  if (prior && prior.parentNode) prior.parentNode.removeChild(prior);

  var overlay = document.createElement("div");
  overlay.id = "_eli3_lr_rw_overlay";
  overlay.className = "_eli3_lr_rw_overlay";

  var box = document.createElement("div");
  box.className = "_eli3_lr_rw_box";
  box.innerHTML =
    '<div class="_eli3_lr_rw_hdr">' +
      '<div class="_eli3_lr_rw_hdr_title">✨ AI REWRITE ASSISTANT</div>' +
      '<button type="button" class="_eli3_lr_rw_close" title="Close">✕</button>' +
    '</div>' +
    '<div class="_eli3_lr_rw_body">' +
      '<div class="_eli3_lr_rw_orig_wrap"' + (isMissing ? ' hidden' : '') + '>' +
        '<div class="_eli3_lr_rw_orig_toggle">' +
          '<div class="_eli3_lr_rw_orig_toggle_left">' +
            '<span class="_eli3_lr_rw_orig_chevron">▶</span>' +
            '<span class="_eli3_lr_rw_orig_label">ORIGINAL CLAUSE</span>' +
          '</div>' +
          '<div class="_eli3_lr_rw_sync_status">⏳ Checking selection…</div>' +
        '</div>' +
        '<div class="_eli3_lr_rw_orig_body" hidden>' +
          '<textarea class="_eli3_lr_rw_orig">' + _esc(originalText) + '</textarea>' +
        '</div>' +
      '</div>' +
      '<div class="_eli3_lr_rw_inst_label">AI INSTRUCTIONS</div>' +
      '<div class="_eli3_lr_rw_inst_row">' +
        '<textarea class="_eli3_lr_rw_inst" rows="4">' + _esc(initialInstruction) + '</textarea>' +
        '<button type="button" class="_eli3_lr_rw_run">↻ RUN</button>' +
      '</div>' +
      '<div class="_eli3_lr_rw_redline_section" hidden>' +
        '<div class="_eli3_lr_rw_redline_header">' +
          '<div class="_eli3_lr_rw_redline_label">REDLINE PREVIEW <span>(click a change to apply it)</span></div>' +
          '<div class="_eli3_lr_rw_redline_header_right">' +
            '<span class="_eli3_lr_rw_hunk_count"></span>' +
            '<button type="button" class="_eli3_lr_rw_redline_toggle" data-on="1" title="Toggle Track Changes for apply">📝 Redlines ON</button>' +
          '</div>' +
        '</div>' +
        '<div class="_eli3_lr_rw_redline_body"></div>' +
      '</div>' +
      '<div class="_eli3_lr_rw_loading">⏳ Generating favorable clause…</div>' +
    '</div>' +
    '<div class="_eli3_lr_rw_footer">' +
      '<button type="button" class="_eli3_lr_rw_apply_all" disabled>✅ APPLY ALL CHANGES</button>' +
      '<button type="button" class="_eli3_lr_rw_full_replace" disabled>📍 FULL REPLACE</button>' +
      '<button type="button" class="_eli3_lr_rw_copy" disabled>📄 Copy</button>' +
    '</div>';
  overlay.appendChild(box);
  document.body.appendChild(overlay);

  var txtOrig         = box.querySelector("._eli3_lr_rw_orig");
  var txtInst         = box.querySelector("._eli3_lr_rw_inst");
  var btnRun          = box.querySelector("._eli3_lr_rw_run");
  var btnApplyAll     = box.querySelector("._eli3_lr_rw_apply_all");
  var btnFull         = box.querySelector("._eli3_lr_rw_full_replace");
  var btnCopy         = box.querySelector("._eli3_lr_rw_copy");
  var btnClose        = box.querySelector("._eli3_lr_rw_close");
  var lblSync         = box.querySelector("._eli3_lr_rw_sync_status");
  var redlineSec      = box.querySelector("._eli3_lr_rw_redline_section");
  var redlineBody     = box.querySelector("._eli3_lr_rw_redline_body");
  var hunkCountLbl    = box.querySelector("._eli3_lr_rw_hunk_count");
  var redlineToggle   = box.querySelector("._eli3_lr_rw_redline_toggle");
  var loadingState    = box.querySelector("._eli3_lr_rw_loading");
  var origToggle      = box.querySelector("._eli3_lr_rw_orig_toggle");
  var origBody        = box.querySelector("._eli3_lr_rw_orig_body");
  var origChevron     = box.querySelector("._eli3_lr_rw_orig_chevron");

  // Redlines ON/OFF toggle. When ON: preview shows the diff (red
  // strike-through old + green new); apply uses per-word track-changes.
  // When OFF: preview shows the AI's proposed text with no markup;
  // apply replaces cleanly without track-changes. Toggle re-renders
  // the preview body so user sees what will land in the doc.
  var _redlinesOn = true;
  if (redlineToggle) {
    redlineToggle.onclick = function () {
      _redlinesOn = !_redlinesOn;
      redlineToggle.setAttribute("data-on", _redlinesOn ? "1" : "0");
      redlineToggle.textContent = _redlinesOn ? "📝 Redlines ON" : "📄 Redlines OFF";
      _paintPreview();
    };
  }

  // Original-clause collapse toggle.
  if (origToggle) {
    origToggle.onclick = function () {
      var hidden = origBody.hasAttribute("hidden");
      if (hidden) origBody.removeAttribute("hidden");
      else origBody.setAttribute("hidden", "");
      origChevron.style.transform = hidden ? "rotate(90deg)" : "rotate(0deg)";
    };
  }

  // State held in closure for handler access.
  var _currentHunks = [];
  var _syncedOriginalText = originalText;
  var _aiResultText = "";

  function _setRunning(running) {
    btnRun.disabled = running;
    btnRun.style.opacity = running ? "0.5" : "";
    btnApplyAll.disabled = running;
    btnFull.disabled = running;
    btnCopy.disabled = running;
  }

  function _runAI() {
    if (!isMissing && (!txtOrig.value || txtOrig.value.trim().length < 2)) return;
    loadingState.removeAttribute("hidden");
    loadingState.textContent = "⏳ Generating favorable clause…";
    redlineSec.setAttribute("hidden", "");
    _setRunning(true);
    var sourceText = txtOrig.value;
    var instr = txtInst.value;
    onRunAI(instr, sourceText, isMissing).then(function (aiText) {
      _aiResultText = String(aiText || "").trim();
      loadingState.setAttribute("hidden", "");
      _setRunning(false);
      btnFull.disabled = false;
      btnCopy.disabled = false;
      if (!isMissing && _syncedOriginalText) {
        _currentHunks = computeDiff(_syncedOriginalText, _aiResultText);
      } else {
        _currentHunks = [];
      }
      _paintPreview();
    }).catch(function (e) {
      loadingState.removeAttribute("hidden");
      loadingState.textContent = "❌ Error: " + (e && e.message || "unknown");
      _setRunning(false);
    });
  }

  // Render the redline preview body. ON: hunk diff with click-to-apply.
  // OFF: clean proposed text (what the apply will land in the doc).
  // Called by _runAI on completion AND by the toggle click.
  function _paintPreview() {
    if (isMissing && _aiResultText) {
      redlineBody.innerHTML = '<div class="_eli3_lr_rw_scratch">' + _esc(_aiResultText) + '</div>';
      hunkCountLbl.textContent = "";
      redlineSec.removeAttribute("hidden");
      btnApplyAll.disabled = true;
      return;
    }
    if (!_aiResultText || !_syncedOriginalText) return;
    var changeCount = (_currentHunks || []).filter(function (h) {
      return h.type === "change" || h.type === "insert" || h.type === "delete";
    }).length;
    if (changeCount === 0) {
      redlineBody.innerHTML = '<div class="_eli3_lr_rw_noop">✅ No differences detected — clause is already aligned.</div>';
      hunkCountLbl.textContent = "";
      redlineSec.removeAttribute("hidden");
      btnApplyAll.disabled = true;
      return;
    }
    redlineSec.removeAttribute("hidden");
    btnApplyAll.disabled = false;
    if (_redlinesOn) {
      // ON — diff view, per-hunk apply enabled.
      redlineBody.innerHTML = renderHunkHtml(_currentHunks);
      hunkCountLbl.textContent = changeCount + " change" + (changeCount > 1 ? "s" : "") + " detected";
      btnApplyAll.textContent = "✅ APPLY ALL " + changeCount + " CHANGES";
      _wireHunkClicks();
    } else {
      // OFF — show proposed text exactly as it will land in the doc.
      redlineBody.innerHTML = '<div class="_eli3_lr_rw_clean">' + _esc(_aiResultText) + '</div>';
      hunkCountLbl.textContent = "Clean replace · " + changeCount + " change" + (changeCount > 1 ? "s" : "");
      btnApplyAll.textContent = "📄 REPLACE CLAUSE";
    }
  }

  function _wireHunkClicks() {
    var els = redlineBody.querySelectorAll(".surgical-hunk");
    els.forEach(function (el) {
      el.onclick = function () {
        var idx = parseInt(el.getAttribute("data-hunk-id"), 10);
        var changeHunks = _currentHunks.filter(function (h) {
          return h.type === "change" || h.type === "insert" || h.type === "delete";
        });
        if (idx < 0 || idx >= changeHunks.length) return;
        var hunk = changeHunks[idx];
        el.style.opacity = "0.5";
        el.style.pointerEvents = "none";
        onApplyHunk(hunk, _currentHunks, _syncedOriginalText, _redlinesOn).then(function (res) {
          if (res && res.ok) {
            var newText = (hunk.newWords || []).join(" ");
            el.innerHTML = '<span class="_eli3_lr_rw_hunk_done">✅ ' + _esc(newText || "[deleted]") + '</span> ';
          } else {
            // Range not found — open hunk jumper for manual locate.
            el.style.opacity = "1";
            el.style.pointerEvents = "auto";
            onLocateAndApply(hunk, el, _syncedOriginalText);
          }
        }).catch(function () {
          el.style.opacity = "1";
          el.style.pointerEvents = "auto";
          onLocateAndApply(hunk, el, _syncedOriginalText);
        });
      };
    });
  }

  // Wire static buttons.
  btnRun.onclick = _runAI;
  btnApplyAll.onclick = function () {
    if (!_syncedOriginalText || !_aiResultText) return;
    var changeHunks = _currentHunks.filter(function (h) {
      return h.type === "change" || h.type === "insert" || h.type === "delete";
    });
    if (!changeHunks.length) return;
    btnApplyAll.disabled = true;
    btnApplyAll.textContent = _redlinesOn ? "⏳ Rebuilding Clause…" : "⏳ Replacing Clause…";
    onApplyAll(_syncedOriginalText, _aiResultText, _currentHunks, _redlinesOn).then(function (res) {
      if (res && res.ok) {
        btnApplyAll.textContent = _redlinesOn ? "✅ REBUILD COMPLETE" : "✅ REPLACED";
        btnApplyAll.classList.add("_eli3_lr_rw_apply_all_done");
        var els = redlineBody.querySelectorAll(".surgical-hunk");
        els.forEach(function (el, idx) {
          el.style.opacity = "0.5";
          el.style.pointerEvents = "none";
          var hunk = changeHunks[idx];
          if (hunk) {
            var n = (hunk.newWords || []).join(" ");
            el.innerHTML = '<span class="_eli3_lr_rw_hunk_done">✅ ' + _esc(n || "[deleted]") + '</span> ';
          }
        });
      } else {
        btnApplyAll.textContent = "❌ Rebuild Failed";
        btnApplyAll.disabled = false;
      }
    }).catch(function () {
      btnApplyAll.textContent = "❌ Rebuild Failed";
      btnApplyAll.disabled = false;
    });
  };
  btnFull.onclick = function () {
    if (!_aiResultText) return;
    onFullReplace(_aiResultText);
    _close();
  };
  btnCopy.onclick = function () {
    if (!_aiResultText) return;
    try { navigator.clipboard.writeText(_aiResultText); } catch (e) {}
    btnCopy.textContent = "✅ COPIED";
    setTimeout(function () { btnCopy.textContent = "📄 Copy"; }, 1500);
  };
  function _close() {
    if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    onClose();
  }
  btnClose.onclick = _close;

  // Initial selection sync — ask init for the cleaned text + status,
  // then auto-run AI. Mirrors v2's auto-sync-on-open behavior.
  onSyncSelection().then(function (sync) {
    sync = sync || {};
    if (sync.cleanText && sync.cleanText.length > 2) {
      txtOrig.value = sync.cleanText;
      _syncedOriginalText = sync.cleanText;
    }
    lblSync.textContent = sync.status || "✔️ Ready";
    if (sync.color) lblSync.style.color = sync.color;
    _runAI();
  }).catch(function () {
    lblSync.textContent = "⚠️ Sync error";
    _syncedOriginalText = txtOrig.value;
    _runAI();
  });

  return {
    overlay: overlay,
    close: _close,
  };
}

// renderHunkJumper — fallback bottom strip shown when applyHunk can't
// uniquely locate the old text. User selects the text manually, clicks
// Apply, init replaces the active selection. FROM v2 showHunkJumper
// (line 23333). All Word ops in init callbacks; view is pure DOM.

view.renderHunkJumper:
function renderHunkJumper(opts) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  opts = opts || {};
  var displayOld = String(opts.displayOldText || opts.oldText || "");
  var newText = String(opts.newText || "");
  var onSearch = opts.onSearch || function () { return Promise.resolve({ found: false }); };
  var onConfirm = opts.onConfirm || function () { return Promise.resolve({ ok: false }); };
  var onCancel = opts.onCancel || function () {};

  // Tear down prior jumper.
  var prior = document.getElementById("_eli3_lr_rw_jumper");
  if (prior && prior.parentNode) prior.parentNode.removeChild(prior);

  var jumper = document.createElement("div");
  jumper.id = "_eli3_lr_rw_jumper";
  jumper.className = "_eli3_lr_rw_jumper";

  var msg = document.createElement("div");
  msg.className = "_eli3_lr_rw_jumper_msg";
  msg.innerHTML = "🔍 Searching document…";

  var btnRow = document.createElement("div");
  btnRow.className = "_eli3_lr_rw_jumper_btns";
  var cancelBtn = document.createElement("button");
  cancelBtn.type = "button";
  cancelBtn.className = "_eli3_lr_rw_jumper_cancel";
  cancelBtn.textContent = "Skip / Cancel";
  var applyBtn = document.createElement("button");
  applyBtn.type = "button";
  applyBtn.className = "_eli3_lr_rw_jumper_apply";
  applyBtn.textContent = "⬇️ Apply Change";
  btnRow.appendChild(cancelBtn);
  btnRow.appendChild(applyBtn);

  jumper.appendChild(msg);
  jumper.appendChild(btnRow);
  document.body.appendChild(jumper);

  function _close() { if (jumper.parentNode) jumper.parentNode.removeChild(jumper); }

  // Run the search to seed the message + selection.
  onSearch().then(function (res) {
    if (res && res.found) {
      msg.innerHTML =
        '✅ Found &amp; selected. Confirm: ' +
        '<span class="_eli3_lr_rw_jumper_del">' + _esc(displayOld) + '</span> → ' +
        '<span class="_eli3_lr_rw_jumper_ins">' + _esc(newText || "[delete]") + '</span>';
      applyBtn.textContent = "✅ Confirm & Apply";
      applyBtn.classList.add("_eli3_lr_rw_jumper_apply_confirm");
    } else if (displayOld) {
      msg.innerHTML =
        '📌 Could not auto-locate. Highlight "<span class="_eli3_lr_rw_jumper_del">' + _esc(displayOld) +
        '</span>" in the document, then click Apply.';
    } else {
      msg.innerHTML =
        '📌 Place cursor where "<span class="_eli3_lr_rw_jumper_ins">' + _esc(newText) + '</span>" should go, then click Apply.';
    }
  }).catch(function () {
    if (displayOld) {
      msg.innerHTML =
        '📌 Highlight "<span class="_eli3_lr_rw_jumper_del">' + _esc(displayOld) +
        '</span>" in the document, then click Apply.';
    } else {
      msg.innerHTML = '📌 Place cursor in the document, then click Apply.';
    }
  });

  cancelBtn.onclick = function () { _close(); onCancel(); };
  applyBtn.onclick = function () {
    applyBtn.textContent = "⏳ Applying…";
    applyBtn.disabled = true;
    onConfirm().then(function (res) {
      _close();
      if (typeof opts.onAfterApply === "function") opts.onAfterApply(res && res.ok);
    }).catch(function () {
      applyBtn.textContent = "❌ Error - Try Again";
      applyBtn.disabled = false;
    });
  };

  return { jumper: jumper, close: _close };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["legal_risks"];
  if (!bundle) return;

  // v2-style smile loader DOM. Closure-scoped so the bundler treats
  // init() as the only top-level function. CSS for .robot-head /
  // .teeth-row / .brush-anim ships with error_review's bundle.
  function _lrPaintSmileLoader() {
    var loader = document.getElementById("loading");
    if (!loader || loader.querySelector(".robot-head")) return;
    loader.style.background = "transparent";
    loader.style.border = "none";
    loader.style.boxShadow = "none";
    loader.innerHTML =
      '<div class="loading-card robot-loader" style="background:transparent;border:none;box-shadow:none;padding:10px 0;">' +
        '<div class="robot-head">' +
          '<div class="robot-eyes"><div class="robot-eye"></div><div class="robot-eye"></div></div>' +
          '<div class="mouth-container">' +
            '<div class="teeth-row upper">' +
              '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
              '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
              '<div class="tooth"></div>' +
            '</div>' +
            '<div class="teeth-row lower">' +
              '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
              '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
              '<div class="tooth"></div>' +
            '</div>' +
            '<div class="brush-anim">🪥</div>' +
            '<div class="foam f1"></div><div class="foam f2"></div><div class="foam f3"></div>' +
          '</div>' +
        '</div>' +
        '<p class="loading-text" style="margin-top:15px;font-weight:700;color:#1565c0;font-size:13px;">Analyzing legal risks…</p>' +
      '</div>';
  }
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var analyze                  = efns.analyze;
  var renderSurgicalRedlineHtml = efns.renderSurgicalRedlineHtml;
  var computeWordDiffV2        = efns.computeWordDiffV2;
  var renderResults            = vfns.renderResults;
  var renderRewriteEditor      = vfns.renderRewriteEditor;
  var renderHunkJumper         = vfns.renderHunkJumper;
  if (!analyze || !renderResults) {
    eli.log.event("tool", "legal_risks_load_failed", {
