      return { text: text, anchors: anchors };
    }).catch(function () {
      return { text: "", anchors: [] };
    });
  }

  // ─── Locate a clause in the document ──────────────────────────────
  // LOCATE button handler. Single source of truth — the engine's
  // normalize step ALWAYS sets item.id to a `_ELI_LR_<n>` bookmark
  // name (or null if AI didn't return one). We jump straight to the
  // bookmark via eli.host.highlightAnchor.
  //
