        '<div style="background:#f8fafc; padding:10px; border-left:3px solid #c62828; font: 500 12px/1.5 Georgia, serif; color:#475569; margin-bottom:14px;">' +
          String(original).replace(/&/g, "&amp;").replace(/</g, "&lt;") + '</div>' +
        '<div style="font-size:11px; color:#1565c0; text-transform:uppercase; letter-spacing:0.4px; margin-bottom:6px;">Suggested</div>' +
        '<div style="background:#fff8e1; padding:10px; border-left:3px solid #1565c0; font: 500 12px/1.5 Georgia, serif; color:#0f172a;">' +
