      ? 'ACT AS: Senior Counsel for Colgate. TASK: Write a brand new clause based strictly on: "' + instruction +
        '". OUTPUT: Only the raw legal text. NO MARKDOWN.'
      : 'ACT AS: Senior Counsel for Colgate. TASK: Rewrite based on: "' + instruction +
        '". CRITICAL: Preserve the original language exactly. Only modify or add the specific words or phrases that need to change. Do NOT rephrase or restructure sentences unnecessarily. ORIGINAL: "' +
        originalText + '". OUTPUT: Only the new legal text. NO MARKDOWN.';
    return eli.ai.complete(prompt, { maxTokens: 1500 }).then(function (text) {
      return String(text || "")
        .replace(/\*\*/g, "").replace(/##/g, "").replace(/__/g, "")
        .replace(/^"|"$/g, "").trim();
    });
