  // Returns {ok, found}. redlinesOn flag toggles changeTrackingMode.
  function _rwApplyHunk(hunk, allHunks, scopeText, anchorId, redlinesOn) {
    if (redlinesOn === undefined) redlinesOn = true;
    var oldText = (hunk.oldWords || []).join(" ");
    var newText = (hunk.newWords || []).join(" ");
    if (!oldText && !newText) return Promise.resolve({ ok: false, found: false });

    var realIdx = allHunks.indexOf(hunk);
    var prevCtx = "", nextCtx = "";
    if (realIdx > 0 && allHunks[realIdx - 1] && allHunks[realIdx - 1].type === "equal") {
      var prevWords = String(allHunks[realIdx - 1].text || "").trim().split(/\s+/);
      if (prevWords.length) prevCtx = prevWords.slice(-2).join(" ") + " ";
    }
    if (realIdx < allHunks.length - 1 && allHunks[realIdx + 1] && allHunks[realIdx + 1].type === "equal") {
      var nextWords = String(allHunks[realIdx + 1].text || "").trim().split(/\s+/);
      if (nextWords.length) nextCtx = " " + nextWords.slice(0, 2).join(" ");
    }
    var paddedOld = (prevCtx + oldText + nextCtx).trim() || oldText;
    var paddedNew = (prevCtx + newText + nextCtx).trim();

    if (!eli.host || typeof eli.host.runRaw !== "function") {
      return Promise.resolve({ ok: false, found: false });
    }
    return eli.host.runRaw("legal_risks:rw_hunk", function (context) {
      var prevTracking = null;
      try { prevTracking = context.document.changeTrackingMode; } catch (e) {}
      return _rwFindClauseRange(context, scopeText, anchorId).then(function (clauseRange) {
        var scope = clauseRange || context.document.body;
        var search = scope.search(paddedOld, {
          matchCase: false, matchWholeWord: false, ignoreSpace: true, ignorePunctuation: true,
        });
        search.load("items");
        return context.sync().then(function () {
          if (!search.items.length) return { ok: false, found: false };
          context.document.changeTrackingMode = redlinesOn ? "TrackAll" : "Off";
          search.items[0].insertText(paddedNew || "", "Replace");
          return context.sync().then(function () {
            if (prevTracking) {
              try { context.document.changeTrackingMode = prevTracking; } catch (e) {}
            }
            return { ok: true, found: true };
          });
        });
      });
