    var displayOld = oldText;
    renderHunkJumper({
      oldText: oldText,
      newText: newText,
      displayOldText: displayOld,
      onSearch: function () {
        if (!eli.host || typeof eli.host.runRaw !== "function") return Promise.resolve({ found: false });
        return eli.host.runRaw("legal_risks:rw_jumper_search", function (context) {
          return _rwFindClauseRange(context, scopeText, anchorId).then(function (clauseRange) {
            var scope = clauseRange || context.document.body;
