        }).then(function (range) {
          if (!range) return { found: false };
          range.select();
          return eli.host.runRaw("legal_risks:rw_jumper_sync", function (context) {
            return context.sync().then(function () { return { found: true }; });
          }).catch(function () { return { found: true }; });
        }).catch(function () { return { found: false }; });
      },
      onConfirm: function () {
        if (!eli.host || typeof eli.host.runRaw !== "function") return Promise.resolve({ ok: false });
        return eli.host.runRaw("legal_risks:rw_jumper_apply", function (context) {
          var prevTracking = null;
          try { prevTracking = context.document.changeTrackingMode; } catch (e) {}
          context.document.changeTrackingMode = "TrackAll";
          var sel = context.document.getSelection();
          sel.insertText(newText || "", "Replace");
          return context.sync().then(function () {
            if (prevTracking) { try { context.document.changeTrackingMode = prevTracking; } catch (e) {} }
            return { ok: true };
          });
        }).catch(function () { return { ok: false }; });
      },
      onAfterApply: function (ok) {
