      },
      onCancel: function () {},
    });
  }

  // Search candidates — full text → 80% → 50% → first 3 words.
  // FROM v2 buildSearchCandidates (line 23357).
  function _rwSearchCandidates(text) {
    var out = [];
    if (!text) return out;
    var clean = text.replace(/[\r\n]+/g, " ").trim();
    if (clean) out.push(clean);
    var words = clean.split(/\s+/);
    if (words.length > 3) out.push(words.slice(0, Math.ceil(words.length * 0.8)).join(" "));
    if (words.length > 4) out.push(words.slice(0, Math.ceil(words.length / 2)).join(" "));
    if (words.length > 3) out.push(words.slice(0, 3).join(" "));
    return out;
  }
  function _rwTryCandidates(context, scope, candidates, idx) {
    if (idx >= candidates.length) return Promise.resolve(null);
    var search = scope.search(candidates[idx], {
      matchCase: false, matchWholeWord: false, ignoreSpace: true, ignorePunctuation: true,
    });
    search.load("items");
    return context.sync().then(function () {
      if (search.items.length) return search.items[0];
      return _rwTryCandidates(context, scope, candidates, idx + 1);
    });
  }

  // Anchor on the original clause for hunk operations. INSIDE runRaw.
  // Priority:
  //   1. Bookmark range at anchorId — exact, constant-time, never wrong.
  //   2. body.search of a 250-char snippet — fuzzy fallback when the
  //      bookmark went missing (user re-paragraphed, accept-changes wiped
  //      it, etc.).
  //   3. null → caller falls back to whole-body scope.
  // Returns Promise<Word.Range|null>.
  function _rwFindClauseRange(context, scopeText, anchorId) {
    if (anchorId) {
      var bm = context.document.getBookmarkRangeOrNullObject(anchorId);
      bm.load("isNullObject");
      return context.sync().then(function () {
        if (!bm.isNullObject) return bm;
        return _rwFindByText(context, scopeText);
      });
    }
    return _rwFindByText(context, scopeText);
  }
  function _rwFindByText(context, scopeText) {
    if (!scopeText) return Promise.resolve(null);
    var snippet = scopeText.substring(0, Math.min(scopeText.length, 250)).replace(/[\r\n\t]+/g, " ").trim();
    if (!snippet) return Promise.resolve(null);
    var results = context.document.body.search(snippet, { matchCase: false, ignoreSpace: true });
    results.load("items");
    return context.sync().then(function () {
      return results.items.length ? results.items[0] : null;
    });
  }

  // FULL REPLACE — open mode picker (port of v2 showRedlinePrompt:
  // taskpane_v2.js:22847). Two options:
  //   • ENABLE REDLINES → tracking ON, full replace at selection
  //   • STANDARD INSERT → tracking OFF, full replace at selection
  // Both branches call _rwExecuteInsert which preserves a leading
  // "Section 5.1 Header:" if the selection has one (v2 executeInsert
  // line 22879 — header-aware replace).
  function _rwFullReplace(aiText) {
    if (!aiText) return;
    if (typeof showEliDialog !== "function") {
      // No dialog primitive — default to track-changes ON.
      _rwExecuteInsert(aiText, true);
      return;
    }
    var dialogOverlay = showEliDialog({
      variant: "info", icon: "📍",
      title: "Insert Options",
      body:
        '<div class="_eli3_lr_rw_insert_picker">' +
          '<button type="button" class="_eli3_lr_rw_insert_redline">' +
            '<span>📝 ENABLE REDLINES</span>' +
            '<span class="_eli3_lr_rw_insert_hint">Track Changes ON</span>' +
          '</button>' +
          '<button type="button" class="_eli3_lr_rw_insert_plain">' +
            '<span>📄 STANDARD INSERT</span>' +
            '<span class="_eli3_lr_rw_insert_hint">No Tracking</span>' +
          '</button>' +
        '</div>',
      secondary: { label: "Cancel" },
    });
    // Wire the two custom-styled buttons inside the body. showEliDialog
    // returns the overlay element — query inside it for our buttons.
    setTimeout(function () {
      var ov = dialogOverlay || document.querySelector(".eli-overlay");
      if (!ov) return;
      var btnRedline = ov.querySelector("._eli3_lr_rw_insert_redline");
      var btnPlain   = ov.querySelector("._eli3_lr_rw_insert_plain");
      if (btnRedline) btnRedline.onclick = function () {
        if (ov.parentNode) ov.parentNode.removeChild(ov);
        _rwExecuteInsert(aiText, true);
      };
      if (btnPlain) btnPlain.onclick = function () {
        if (ov.parentNode) ov.parentNode.removeChild(ov);
        _rwExecuteInsert(aiText, false);
      };
    }, 0);
  }

  // FROM v2 executeInsert (line 22879). Replaces the user's selection
  // with the AI text. If the selection starts with a numbered/lettered
  // header ("5.1 Liability:" / "Section 3 Indemnification."), the
  // header is preserved and only the body is replaced.
  function _rwExecuteInsert(text, turnOnRedlines) {
    if (!eli.host || typeof eli.host.runRaw !== "function") return;
    if (typeof showToast === "function") {
      showToast(turnOnRedlines ? "📝 Inserting (Redlines ON)…" : "📄 Inserting…", "info");
    }
    var safeText = String(text || "").replace(/\r?\n/g, "");
    eli.host.runRaw("legal_risks:rw_execute_insert", function (context) {
      var prevTracking = null;
      try { prevTracking = context.document.changeTrackingMode; } catch (e) {}
      context.document.changeTrackingMode = turnOnRedlines ? "TrackAll" : "Off";
      var sel = context.document.getSelection();
      sel.load("text");
      return context.sync().then(function () {
        var rangeToReplace = sel;
        var preservedHeader = false;
        var origText = (sel.text || "").trim();
        var headerRx = /^((?:Section\s*)?[\d\.]+\s*)?([A-Z][A-Za-z0-9\s]+)(:|\.)\s+/;
        var headerMatch = origText.match(headerRx);
        if (headerMatch) {
          var headerStr = headerMatch[0];
          var hr = sel.search(headerStr, { matchCase: false });
          hr.load("items");
          return context.sync().then(function () {
            if (hr.items.length) {
              var headerRange = hr.items[0];
              var bodyStart = headerRange.getRange("End");
              var bodyEnd = sel.getRange("End");
              rangeToReplace = bodyStart.expandTo(bodyEnd);
              preservedHeader = true;
            }
            return _rwInsertWithFmt(context, rangeToReplace, safeText, preservedHeader, prevTracking);
          });
        }
        return _rwInsertWithFmt(context, rangeToReplace, safeText, false, prevTracking);
      });
    }).then(function () {
      if (typeof showToast === "function") {
        showToast(turnOnRedlines ? "📝 Inserted (Redlines ON)" : "✅ Inserted", "ok");
      }
    }).catch(function (e) {
      if (typeof showToast === "function") showToast("Insert failed: " + (e && e.message || "unknown"), "err");
    });
  }
  function _rwInsertWithFmt(context, rangeToReplace, safeText, preservedHeader, prevTracking) {
    rangeToReplace.font.load("name, size, bold, italic");
    return context.sync().then(function () {
      var inserted = rangeToReplace.insertText(safeText, "Replace");
      if (preservedHeader) {
        inserted.font.bold = false;
        inserted.font.italic = false;
        inserted.font.underline = "None";
        if (rangeToReplace.font.name) inserted.font.name = rangeToReplace.font.name;
        if (rangeToReplace.font.size) inserted.font.size = rangeToReplace.font.size;
      } else {
        if (rangeToReplace.font.name) inserted.font.name = rangeToReplace.font.name;
        if (rangeToReplace.font.size) inserted.font.size = rangeToReplace.font.size;
        inserted.font.bold = rangeToReplace.font.bold;
        inserted.font.italic = rangeToReplace.font.italic;
      }
      return context.sync().then(function () {
        if (prevTracking) {
          try { context.document.changeTrackingMode = prevTracking; } catch (e) {}
        }
      });
    });
  }

  // Run the kernel-level surgical redline + surface result toast.
  // Falls back to ask_eli's action-card path on coarse-replace (range
  // not found) so the user always has a path forward.
  function _applySurgicalNow(originalText, newText) {
    if (!eli.host || typeof eli.host.applySurgicalRedline !== "function") {
      // Kernel doesn't have the helper yet — fall back to ask_eli.
      var askEliCompose = eli.get && eli.get("ask_eli", "compose");
      if (typeof askEliCompose === "function") {
        try {
          askEliCompose({
            question: "Apply this rewrite with track changes.",
            context: [
              { role: "user", content: "Rewrite this clause:\n\n" + originalText },
              { role: "model", content: newText },
            ],
          });
          return;
        } catch (e) {}
      }
      if (typeof showToast === "function") showToast("Surgical apply requires kernel update (paste latest taskpane_v3.js).", "warn");
      return;
    }
    if (typeof showToast === "function") showToast("⚡ Applying with track changes…", "info");
    eli.host.applySurgicalRedline({
      originalText: originalText,
      newText: newText,
      preserveFormatting: true,
    }).then(function (res) {
      if (!res) return;
      if (res.precision === "minimal") {
        if (typeof showToast === "function") showToast("✓ Applied with surgical track changes.", "ok");
      } else if (res.precision === "noop") {
        if (typeof showToast === "function") showToast("✓ No change — rewrite matches original.", "info");
      } else {
        // Coarse — range not found. Offer a manual review path.
        if (typeof showToast === "function") {
          showToast("Couldn't pinpoint the clause — try LOCATE first, then re-run FIX.", "warn");
        }
      }
    }).catch(function (err) {
      eli.log.event("tool", "legal_risks_apply_failed", { msg: err && err.message });
      if (typeof showToast === "function") showToast("Apply failed: " + (err && err.message || "unknown"), "err");
    });
  }

  // DELETE — surgical empty-replace via the same kernel helper.
  function _deleteClause(item) {
    var original = String(item.text || "").trim();
    if (!original) {
      if (typeof showToast === "function") showToast("No clause text to delete.", "warn");
      return;
    }
    if (typeof showEliDialog === "function") {
      showEliDialog({
        variant: "danger",
        icon: "🗑️",
        title: "Delete this clause?",
        body: '<div style="font: 500 12px/1.5 Georgia, serif; color:#475569; background:#fef2f2; padding:10px; border-left:3px solid #c62828;">' +
          String(original).replace(/&/g, "&amp;").replace(/</g, "&lt;") + '</div>',
        primary: {
          label: "🗑️ Delete with track changes",
          onclick: function () { _applySurgicalNow(original, ""); },
        },
        secondary: { label: "Cancel" },
      });
    } else {
      _applySurgicalNow(original, "");
    }
  }

  // ─── DISMISS — track in session feed ──────────────────────────────
