      if (!outEl) return;
      mount = document.createElement("div");
      mount.id = "_eli3_dashboard_root";
      outEl.appendChild(mount);
    }
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedRisk"); } catch (e) {}
    try {
      var cur = eli.fsm.getCurrent ? eli.fsm.getCurrent() : null;
      if (cur === "idle") eli.fsm.transition("scanning");
    } catch (e) {}

    // Show a loading overlay while the AI runs.
    try { _lrPaintSmileLoader(); } catch (_) {}
