      var _engineInput = {
        text: doc.text,
        rules: rules,
        docType: docType,
        showUsage: showUsage,
        docHash: _hashContent(doc.text),
      };
      return analyze(_engineInput, { ai: eli.ai, host: eli.host, storage: eli.storage }).then(function (result) {
        if (eli.wrongness) eli.wrongness.capture("legal_risks", _engineInput, result, {});
        return result;
      });
    }).then(function (result) {
      try { if (eli.stats && eli.stats.record) eli.stats.record("docsReviewed"); } catch (e) {}
      if (result.items && result.items.length) {
        try { eli.stats.record("risksFound", result.items.length); } catch (e) {}
      }
      // Event-based trophy evaluator: Bullseye (t105 — exactly 20 risks),
      // Early Bird (t114 — before 8 AM), Leap Year Logician (t134 — Feb 29).
      try {
        if (eli.trophies && typeof eli.trophies.evaluate === "function") {
          eli.trophies.evaluate("risk_scan_complete", {
            totalRisks: (result.items || []).length,
            wordCount: (doc.text || "").split(/\s+/).filter(Boolean).length,
