        },
        onLocate: function (item) { _locateClause(item); },
        onFix:    function (item) { _fixClause(item); },
        onDelete: function (item) { _deleteClause(item); },
        onDismiss: function (item) { _dismissItem(item); },
        // Speed-reader easter egg: closing the results within 3s of
        // render counts as a "speed_reader" trophy event. Trophy
        // gallery's queue handler dedups per session so it can't
        // re-fire on the same trophy id.
        onCloseFast: function () {
          try { eli.dispatch && eli.dispatch("trophies", "unlocked", {
            id: "speed_reader",
            icon: "⚡",
            title: "Speed Reader",
            desc: "Closed Legal Risks within 3 seconds of opening.",
          }); } catch (e) {}
        },
      });

