        var rCount = (result.items || []).filter(function (i) { return i.category === "Risk"; }).length;
        var tMatch = (result.raw && result.raw._docTextForCount) ||
          (typeof doc !== "undefined" && doc.text) || "";
        var defined = String(tMatch).match(/[A-Z][a-z]+(?=\s+(?:means|shall mean|is defined as))/g);
        var tCount = defined ? new Set(defined).size : 0;
        if (rCount > 0 || tCount > 0) {
          eli.dispatch && eli.dispatch("trophies", "unlocked", {
            id: "deal360",
            icon: "📊",
            title: "Deal 360°",
            desc: "Scanned a document with the Legal Risks engine.",
            riskCount: rCount,
            termCount: tCount,
          });
        }
      } catch (e) {}

      // FROM v2: Compare integration. When the launcher passed a
      // comparePayload (Compare Draft picker chose template / past version /
      // uploaded file), call compare:run which fires PROMPTS.COMPARE and
      // renders the missing/deviations/additions buckets into
      // _eli3_lr_compare_target, which sits at the top of the risks view.
      if (launcherCfg && launcherCfg.comparePayload && eli.get) {
        var compareHandler = eli.get("compare", "run");
        if (typeof compareHandler === "function") {
          try {
            compareHandler({
              payload: launcherCfg.comparePayload,
              mode: launcherCfg.compareMode || "new",
              targetId: "_eli3_lr_compare_target",
            });
          } catch (e) {
            eli.log.event("tool", "legal_risks_compare_handoff_failed", { msg: e && e.message });
          }
        } else {
          eli.log.event("tool", "legal_risks_compare_handler_missing", {});
        }
        // One-shot — don't re-run on next scan.
        try { delete launcherCfg.comparePayload; } catch (e) {}
      }

      // Activity feed — restorable entry so clicking re-renders this view.
      var summary;
      if (!result.items || !result.items.length) {
        summary = "✅ No risks detected";
      } else {
        var parts = [];
        if (result.riskCount) parts.push(result.riskCount + " Risk" + (result.riskCount !== 1 ? "s" : ""));
        if (result.usageCount) parts.push(result.usageCount + " Ops");
        summary = parts.join(" · ") + " detected";
      }
      var durationMs = Date.now() - scanStartTs;
      if (eli.activity && eli.activity.add) {
        try {
          var entry = eli.activity.add({
            type: "legal-360",
            icon: "⚡",
            label: "Legal Risks",
            summary: summary,
            payload: result,
            durationMs: durationMs,
            provenance: result.provenance,
            restoreChannel: "activity_restore",
            restoreKey: "legal-360",
          });
          // Stash entry id + total count so _fixClause can bump
          // _fixedCount and rewrite the summary on each FIX (v2 parity).
          if (entry && entry.id) {
            _latestLegal360EntryId = entry.id;
            _latestLegal360Total = (result.items || []).length;
            _latestLegal360Fixed = 0;
          }
        } catch (e) {}
      }
    }).catch(function (err) {
      if (typeof setLoading === "function") {
        try { setLoading(false); } catch (e) {}
      }
      eli.log.event("tool", "legal_risks_open_failed", { msg: err && err.message });
      if (err && err.message && /abort|cancel/i.test(err.message)) {
        if (typeof showCancelledState === "function") showCancelledState();
        return;
      }
      if (typeof showToast === "function") {
        showToast("Analysis failed: " + (err && err.message || "unknown"), "err");
      }
    });
  }

  // ─── Activity-feed restore — re-renders a past Legal Risks result ─
  function _restoreActivity(payload) {
    if (!payload) return;
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) {
      if (typeof showToast === "function") showToast("Dashboard root missing", "err");
      return;
    }
    try { eli.fsm.transition("rendering"); } catch (e) {}
    // payload may be the result object OR the wrapper with .items.
    var data = (payload && payload.items) ? payload : (payload.raw || { items: [] });
    // Optional section filter — caller passes `payload.sectionLabel`
    // to render only risks attached to a particular section
    // (selection-panel "Scan this section" flow). When set, we filter
    // items via the engine helper before painting.
    if (payload && payload.sectionLabel && Array.isArray(data.items)) {
      data = Object.assign({}, data, {
        items: _filterItemsForSection(data.items, payload.sectionLabel),
      });
    }
    var rulesActive = !!(payload.rulesActive || (payload.raw && payload.raw._rulesWereActive));
    renderResults({
      mount: mount,
      data: data,
      rulesActive: rulesActive,
      showUsage: true,
      onHome: function () {
        try { eli.fsm.transition("idle"); } catch (e) {}
        if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
      },
      onLocate: function (item) { _locateClause(item); },
      onFix:    function (item) { _fixClause(item); },
      onDelete: function (item) { _deleteClause(item); },
      onDismiss: function (item) { _dismissItem(item); },
    });
  }

  // ─── Section filter helper (FROM v2 legalRisksFilterForSection) ───
  // Filter a Legal Risks items list down to entries that reference
  // the supplied section label. Loose match — substring either way
  // because the AI sometimes uses different naming conventions for
  // the section ("Confidentiality", "Section 5", "Article 5.2", etc.)
  // and the caller might pass any of those forms.
  function _filterItemsForSection(items, sectionLabel) {
    if (!Array.isArray(items)) return [];
    var sLow = String(sectionLabel || "").toLowerCase();
    if (!sLow) return items;
    return items.filter(function (r) {
      if (!r) return false;
      var ref = String(r.section || r.section_ref || r.clause_ref || r.location || "").toLowerCase();
      if (!ref) return false;
      return ref.indexOf(sLow) !== -1 || sLow.indexOf(ref) !== -1;
    });
  }

  // Rules Manager launcher — opens the v2 rules CRUD UI ported into
  // this tool (rulesManager.js). Closure-bound entry point so cross-tool
  // dispatch can hit it without exposing the function name globally.
  function _openRulesManager() {
    if (typeof lrShowRiskRulesManager === "function") {
      try { lrShowRiskRulesManager(); }
      catch (e) {
        eli.log.event("tool", "legal_risks_rules_manager_failed", { msg: e && e.message });
        if (typeof showToast === "function") showToast("Rules Manager failed: " + (e.message || "unknown"), "err");
      }
    } else if (typeof showToast === "function") {
      showToast("Rules Manager not loaded — reload the taskpane.", "warn");
    }
  }

  // ─── Channels ─────────────────────────────────────────────────────
  eli.register({
    tile: { app_legal_risks: function () { _open(); } },
    // Settings entry (Legal Review's settings menu dispatches here).
    tile_settings: { app_legal_risks: _openRulesManager },
    // Programmatic launch from legal_review's Launch Analysis.
    legal_risks: {
      run: _open,
      // Open the Risk Rules CRUD UI. Wire-up: settings menus call
      // eli.dispatch("legal_risks", "showRulesManager") to reach this.
      showRulesManager: _openRulesManager,
      // Section-scoped read of the most recent legal-360 entry —
      // used by the selection panel's inline "Scan this section"
      // card. Returns a Promise<items[]> filtered to the section.
      filterForSection: function (sectionLabel) {
        if (!eli.activity || typeof eli.activity.list !== "function") return Promise.resolve([]);
        try {
          var entries = eli.activity.list({ limit: 50 }) || [];
          var hit = entries.filter(function (e) {
            return e && e.type === "legal-360" && e.payload;
          })[0];
          if (!hit) return Promise.resolve([]);
          var items = (hit.payload && hit.payload.items) || [];
          return Promise.resolve(_filterItemsForSection(items, sectionLabel));
        } catch (e) { return Promise.resolve([]); }
      },
    },
    // Activity-feed restore.
    activity_restore: { "legal-360": _restoreActivity },
  });

  // Back-compat shims for v2 callers.
  window.runDeal360Analysis = function () { _open(); };
  window.showRiskRulesManager = function () { _openRulesManager(); };

  eli.log.event("tool", "legal_risks_initialized", {});
}

jsonTools.css:
/* legal_risks tool styles — port of v2 renderBalancedResults markup.
   Class-driven CSS replaces v2's inline-styles for maintainability.
   Injected as <style data-tool="legal_risks">. */

._eli3_lr_results {
  background: #f8f9fa;
  font-family: Inter, sans-serif;
  /* Mounts into #_eli3_dashboard_root which is `display: flex; flex-
   * direction: row` (built for sidebar|main). To take over the whole
   * tool window we need to fill the row's only child slot. flex:1 +
   * min-height:0 mirrors the kernel's .tool-panel primitive
   * (taskpane_v3.css §11) without coupling to that class name. */
  flex: 1 1 auto;
  width: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}

/* ── Header ───────────────────────────────────────────────────────── */
._eli3_lr_results_header {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  padding: 12px 15px;
  border-bottom: 3px solid #c9a227;
  margin-bottom: 15px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-shrink: 0;
}
._eli3_lr_results_title {
  font: 700 18px/1.1 Georgia, serif;
  color: #fff;
}
._eli3_lr_results_close {
  background: transparent;
  border: 0;
  font: 700 16px/1 'Inter', sans-serif;
  color: rgba(255, 255, 255, 0.85);
  cursor: pointer;
  padding: 2px 8px;
  transition: color 0.15s;
}
._eli3_lr_results_close:hover { color: #fff; }

/* ── Rules-active banner ──────────────────────────────────────────── */
._eli3_lr_results_rules_banner {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 8px 15px 8px;
  padding: 10px;
  background: #e8f5e9;
  border: 1px solid #c8e6c9;
  border-left: 5px solid #2e7d32;
}
._eli3_lr_results_rules_icon { font-size: 18px; }
._eli3_lr_results_rules_eyebrow {
  font: 800 10px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #1b5e20;
  margin-bottom: 2px;
}
._eli3_lr_results_rules_sub {
  font: 500 10px/1.3 'Inter', sans-serif;
  color: #2e7d32;
}

/* ── Issues Overview (collapsible) ────────────────────────────────── */
._eli3_lr_results_overview_head {
  cursor: pointer;
  margin: 0 14px 10px 14px;
  padding: 6px 10px;
  background: rgba(21, 101, 192, 0.08);
  border-left: 3px solid #1565c0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  user-select: none;
}
._eli3_lr_results_overview_label {
  font: 800 12px/1 'Inter', sans-serif;
  color: #1565c0;
  text-transform: uppercase;
  flex: 1;
}
._eli3_lr_results_overview_hint {
  font: 700 9px/1 'Inter', sans-serif;
  color: #1565c0;
  opacity: 0.6;
  letter-spacing: 1px;
  flex: 1;
  text-align: center;
  transition: opacity 0.2s;
  white-space: nowrap;
}
._eli3_lr_results_overview_arrow {
  font: 500 10px/1 'Inter', sans-serif;
  color: #1565c0;
  flex: 1;
  text-align: right;
}
._eli3_lr_results_overview_card {
  margin: 0 14px 15px 14px;
  padding: 15px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 5px solid #1565c0;
}
._eli3_lr_results_overview_title {
  font: 700 15px/1.3 'Inter', sans-serif;
  color: #1565c0;
  margin-bottom: 5px;
}
._eli3_lr_results_overview_balance {
  font: 500 13px/1.5 'Inter', sans-serif;
  color: #37474f;
