/* ── Section header (Risks/Usage) ─────────────────────────────────── */
._eli3_lr_results_section_wrap {
  margin-bottom: 16px;
}
._eli3_lr_results_section_head {
  background: #c62828;
  padding: 10px 14px;
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  user-select: none;
}
._eli3_lr_results_section_icon { font-size: 15px; }
._eli3_lr_results_section_title {
  font: 800 13px/1 'Inter', sans-serif;
  color: #fff;
  letter-spacing: 0.3px;
  text-transform: uppercase;
