._eli3_lr_results_card_num {
  font: 700 14px/1.4 'Inter', sans-serif;
  margin-right: 4px;
}
._eli3_lr_results_card_title {
  font: 700 14px/1.4 'Inter', sans-serif;
  color: #0f172a;
