  text-transform: uppercase;
  background: rgba(139, 92, 246, 0.12);
  color: #6d28d9;
  border: 1px solid rgba(139, 92, 246, 0.35);
  vertical-align: middle;
}
._eli3_lr_results_card_quote {
  font: italic 500 12px/1.4 'Georgia', serif;
  color: #546e7a;
  margin-bottom: 8px;
  background: #f9f9f9;
  padding: 6px 8px;
  border-radius: 3px;
}
._eli3_lr_results_card_analysis {
  font: 500 13px/1.5 'Inter', sans-serif;
  color: #333;
}
._eli3_lr_results_card_suggest {
  margin-top: 8px;
  background: #fff8e1;
  padding: 8px;
  border: 1px solid #ffe0b2;
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #e65100;
}
._eli3_lr_results_card_watchout {
  margin-top: 8px;
  background: #fff3cd;
  padding: 8px;
  border-left: 3px solid #ffc107;
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #856404;
}
._eli3_lr_results_card_actions {
  display: flex;
  gap: 5px;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px dashed #eee;
}

/* ── Card action buttons ──────────────────────────────────────────── */
._eli3_lr_results_btn {
  flex: 1;
  padding: 7px 8px;
  font: 800 10px/1 'Inter', sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  border: 1px solid #cbd5e1;
